=====================================================

Here is a basic implementation of a singly linked list in C++ with methods for insertion, deletion, and searching.

```cpp
// node.h

#ifndef NODE_H
#define NODE_H

class Node {
public:
    int data;
    Node* next;

    // Constructor to initialize the node
    Node(int value) : data(value), next(nullptr) {}
};

#endif // NODE_H
```

```cpp
// linked_list.h

#ifndef LINKED_LIST_H
#define LINKED_LIST_H

#include "node.h"

class LinkedList {
public:
    Node* head;  // Head of the list

    // Constructor to initialize the list
    LinkedList() : head(nullptr) {}

    // Insert a new node at the end of the list
    void insert(int value);

    // Delete a node with the given value from the list
    bool deleteNode(int value);

    // Search for a node with the given value in the list
    Node* search(int value);
};

#endif // LINKED_LIST_H
```

```cpp
// linked_list.cpp

#include "linked_list.h"
#include <iostream>

void LinkedList::insert(int value) {
    Node* newNode = new Node(value);

    if (head == nullptr) {
        head = newNode;
    } else {
        Node* current = head;

        while (current->next != nullptr) {
            current = current->next;
        }

        current->next = newNode;
    }
}

bool LinkedList::deleteNode(int value) {
    if (head == nullptr) return false;  // List is empty

    if (head->data == value) {
        Node* temp = head;
        head = head->next;
        delete temp;
        return true;
    }

    Node* current = head;

    while (current->next != nullptr) {
        if (current->next->data == value) {
            Node* temp = current->next;
            current->next = current->next->next;
            delete temp;
            return true;
        }
        current = current->next;
    }

    return false;  // Value not found
}

Node* LinkedList::search(int value) {
    Node* current = head;

    while (current != nullptr) {
        if (current->data == value) {
            return current;
        }
        current = current->next;
    }

    return nullptr;  // Value not found
}
```

```cpp
// main.cpp

#include "linked_list.h"
#include <iostream>

int main() {
    LinkedList list;

    list.insert(10);
    list.insert(20);
    list.insert(30);

    std::cout << "List: ";
    Node* current = list.head;
    while (current != nullptr) {
        std::cout << current->data << " ";
        current = current->next;
    }
    std::cout << std::endl;

    Node* found = list.search(20);
    if (found != nullptr) {
        std::cout << "Found node with value 20" << std::endl;
    } else {
        std::cout << "Node with value 20 not found" << std::endl;
    }

    bool deleted = list.deleteNode(20);
    if (deleted) {
        std::cout << "Deleted node with value 20" << std::endl;
    } else {
        std::cout << "Node with value 20 not found to delete" << std::endl;
    }

    return 0;
}
```

This implementation provides a basic singly linked list class `LinkedList` with methods for insertion, deletion, and searching. The linked list is composed of nodes, each containing an integer data field and a reference to the next node in the list.

The example usage demonstrates how to create a linked list, insert nodes, search for a node by value, delete a node by value, and print the contents of the list.

